{
  "segment_function": "Examines the nature of power, distinguishing it from strength and force, and analyzes how tyranny relies on isolation and contradicts human plurality, rendering itself impotent.",
  "claims": [
    {
      "claim": "Power is generated exclusively by the living together of people and the constant presence of the potentialities of action, and whoever isolates himself forfeits power regardless of his strength.",
      "claim_type": "author_position",
      "supporting_excerpt": "The only indispensable material factor in the generation of power is the living together of people. Only where men live so close together that the potentialities of action are always present can power remain with them... And whoever, for whatever reasons, isolates himself and does not partake in such being together, forfeits power and becomes impotent, no matter how great his strength and how valid his reasons.",
      "support_kind": "direct",
      "qualifications": [
        "Dependent on living close together where potentialities of action are present"
      ],
      "confidence": 1
    },
    {
      "claim": "Tyranny rests on isolation—both of the tyrant from subjects and of subjects from each other—and thus contradicts human plurality, generating impotence rather than power.",
      "claim_type": "author_position",
      "supporting_excerpt": "Montesquieu realized that the outstanding characteristic of tyranny was that it rested on isolation—on the isolation of the tyrant from his subjects and the isolation of the subjects from each other through mutual fear and suspicion—and hence that tyranny was not one form of government among others but contradicted the essential human condition of plurality",
      "support_kind": "direct",
      "qualifications": [
        "In Montesquieu's interpretation"
      ],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "Power",
      "definition": "A potentiality in being together that is boundless, corresponds to human plurality, and can be divided and generated through the interplay of powers."
    },
    {
      "term": "Strength",
      "definition": "An individual attribute that is indivisible, has physical limitations in human bodily existence, and is kept in bounds by the presence of others."
    },
    {
      "term": "Force",
      "definition": "That which one man alone can exert against fellow men and of which one or a few can possess a monopoly by acquiring the means of violence."
    }
  ],
  "distinctions": [
    {
      "item_a": "Power",
      "item_b": "Strength",
      "distinction": "Power is a potentiality dependent on being together and plurality, and can be divided without decreasing it, whereas strength is indivisible, has physical limitations in bodily existence, and can be overpowered by the power of the many."
    },
    {
      "item_a": "Power",
      "item_b": "Force",
      "distinction": "Power depends on the temporary agreement of many wills and cannot be possessed like strength or applied like force, while force can be exerted by one person alone through violence."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "Power requires the living together of people and corresponds to the condition of plurality.",
    "Tyranny rests on isolation, contradicts plurality, and condemns rulers and ruled to impotence."
  ]
}

